import React, { useState, useEffect } from 'react';
import Web3 from 'web3';
import './App.css';

const CONTRACT_ADDRESS = '0xFabfa00EB40ecC984Be0a7A3797AE14977069135';
const CONTRACT_ABI = [
  {"inputs":[],"stateMutability":"nonpayable","type":"constructor"},
  {"anonymous":false,"inputs":[{"indexed":false,"internalType":"string","name":"newGreeting","type":"string"},{"indexed":true,"internalType":"address","name":"changer","type":"address"}],"name":"GreetingChanged","type":"event"},
  {"inputs":[],"name":"getGreeting","outputs":[{"internalType":"string","name":"","type":"string"}],"stateMutability":"view","type":"function"},
  {"inputs":[],"name":"owner","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},
  {"inputs":[{"internalType":"string","name":"_greeting","type":"string"}],"name":"setGreeting","outputs":[],"stateMutability":"nonpayable","type":"function"}
];

function App() {
  const [contract, setContract] = useState(null);
  const [account, setAccount] = useState('');
  const [greeting, setGreeting] = useState('جاري التحميل...');
  const [newGreeting, setNewGreeting] = useState('');
  const [status, setStatus] = useState('');

  useEffect(() => {
    const init = async () => {
      if (!window.ethereum) {
        setStatus('يرجى تثبيت MetaMask');
        return;
      }

      try {
        const web3 = new Web3(window.ethereum);
        const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
        setAccount(accounts[0]);

        const contractInstance = new web3.eth.Contract(CONTRACT_ABI, CONTRACT_ADDRESS);
        setContract(contractInstance);
        loadGreeting(contractInstance);
      } catch (err) {
        setStatus('فشل الاتصال');
      }
    };
    init();
  }, []);

  const loadGreeting = async (contractInstance) => {
    try {
      const msg = await contractInstance.methods.getGreeting().call();
      setGreeting(msg);
    } catch (err) {
      setStatus('فشل في التحميل');
    }
  };

  const handleSetGreeting = async () => {
    if (!newGreeting.trim()) return setStatus('اكتب رسالة');
    if (!contract) return setStatus('اربط MetaMask أولاً');
    setStatus('جاري الإرسال...');
    try {
      await contract.methods.setGreeting(newGreeting).send({ from: account });
      setStatus('تم التغيير! جاري التحديث...');
      setNewGreeting('');
      setTimeout(() => loadGreeting(contract), 3000);
    } catch (err) {
      setStatus(err.message.includes('User denied') ? 'تم رفض المعاملة' : 'فشل الإرسال');
    }
  };

  const connectWallet = async () => {
    if (window.ethereum) {
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      setAccount(accounts[0]);
    }
  };

  return (
    <div className="min-h-screen bg-creek-dark text-white p-8">
      <header className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold text-creek-green">Hello Arc</h1>
        <button onClick={connectWallet} className="bg-creek-green px-6 py-2 rounded-lg font-bold">
          {account ? `${account.slice(0,6)}...${account.slice(-4)}` : 'ربط MetaMask'}
        </button>
      </header>
      <div className="max-w-md mx-auto bg-gray-900 p-6 rounded-xl shadow-lg">
        <div className="text-center mb-6">
          <h2 className="text-xl mb-4">الرسالة الحالية</h2>
          <div className="bg-gray-800 p-4 rounded-lg text-lg font-mono">"{greeting}"</div>
        </div>
        <input
          type="text"
          value={newGreeting}
          onChange={(e) => setNewGreeting(e.target.value)}
          placeholder="اكتب رسالة جديدة..."
          className="w-full p-3 bg-gray-800 rounded-lg mb-4 text-white placeholder-gray-400"
        />
        <button onClick={handleSetGreeting} className="w-full bg-creek-green py-3 rounded-lg font-bold hover:bg-green-600 transition">
          تغيير الرسالة
        </button>
        <p className="mt-4 text-sm text-gray-400 text-center">{status}</p>
      </div>
    </div>
  );
}

export default App;
